def compute(vars):
    revenue = vars["v2"]
    cost_of_revenues = vars["v1"]
    if revenue == 0:
        return None
    result = (cost_of_revenues / revenue) * 100
    return {
        "value": result,
        "trace": {
            "cost_of_revenues": cost_of_revenues,
            "revenue": revenue,
            "ratio": cost_of_revenues / revenue,
            "output_meta": {
                "currency": "CNY",
                "scale": "million",
                "unit": "percentage"
            }
        }
    }
